  // página de inicio
  "home.nav.aria": { es: "Principal", en: "Main" },
  "home.meta.description": { es: "CredoSeal: emita credenciales digitales firmadas, entréguelas en cualquier wallet y verifíquelas en segundos. Confianza que se puede verificar.", en: "CredoSeal: issue signed digital credentials, deliver them to any wallet and verify them in seconds. Trust you can verify." },
  "home.cta.start": { es: "Empezar gratis", en: "Start for free" },
  "home.nav.login": { es: "Iniciar sesión", en: "Sign in" },
  "home.problem.1.title": { es: "Fáciles de falsificar", en: "Easy to forge" },
  "home.problem.1.body": { es: "PDFs, fotos y papeles se editan en minutos, y quien los recibe no tiene cómo saberlo.", en: "PDFs, photos and paper can be edited in minutes, and whoever receives them has no way to tell." },
  "home.problem.2.title": { es: "Verificar es lento", en: "Checking is slow" },
  "home.problem.2.body": { es: "Correos, llamadas y esperas para confirmar algo que debería ser instantáneo.", en: "Emails, phone calls and waiting to confirm something that should be instant." },
  "home.problem.3.title": { es: "Se comparte de más", en: "Too much gets shared" },
  "home.problem.3.body": { es: "Para probar un solo dato se entrega el documento entero, con todos los datos personales.", en: "To prove a single fact, people hand over the whole document and every personal detail on it." },
  "home.how.1.title": { es: "Emita", en: "Issue" },
  "home.how.1.body": { es: "Defina el tipo de credencial con un formulario y emita desde el panel o la API. Cada credencial va firmada con la clave de su organización.", en: "Define the credential type with a form and issue from the dashboard or the API. Every credential is signed with your organization's key." },
  "home.how.2.title": { es: "Entregue", en: "Deliver" },
  "home.how.2.body": { es: "La persona la recibe con un enlace y un código: en Apple Wallet, Google Wallet o una wallet de credenciales OpenID4VCI.", en: "The person receives it with a link and a code: in Apple Wallet, Google Wallet or an OpenID4VCI credential wallet." },
  "home.how.3.title": { es: "Verifique", en: "Verify" },
  "home.how.3.body": { es: "Cualquiera la comprueba al instante: firma, vigencia y revocación, mostrando sólo los datos necesarios.", en: "Anyone can check it instantly: signature, validity and revocation, showing only the data that's needed." },
  "home.uses.membership.title": { es: "Membresías y acceso", en: "Memberships and access" },
  "home.uses.membership.body": { es: "Socios, clubes, coworkings y eventos con una acreditación que se verifica en la puerta.", en: "Members, clubs, coworking spaces and events with a pass that's verified at the door." },
  "home.uses.employment.title": { es: "Empleo y RR. HH.", en: "Employment and HR" },
  "home.uses.employment.body": { es: "Constancias laborales, habilitaciones y referencias que el próximo empleador comprueba solo.", en: "Employment records, clearances and references the next employer checks on their own." },
  "home.uses.licenses.title": { es: "Licencias profesionales", en: "Professional licenses" },
  "home.uses.licenses.body": { es: "Matrículas y habilitaciones que se validan contra el emisor en tiempo real.", en: "Registrations and permits validated against the issuer in real time." },
  "home.uses.education.title": { es: "Educación y formación", en: "Education and training" },
  "home.uses.education.body": { es: "Títulos, cursos y microcredenciales imposibles de falsificar.", en: "Degrees, courses and micro-credentials that can't be forged." },
  "home.uses.supply.title": { es: "Proveedores y cadena de suministro", en: "Suppliers and supply chain" },
  "home.uses.supply.body": { es: "Certificaciones de calidad, origen y cumplimiento entre empresas.", en: "Quality, origin and compliance certifications between companies." },
  "home.uses.identity.title": { es: "Identidad y edad", en: "Identity and age" },
  "home.uses.identity.body": { es: "Pruebas de edad o de pertenencia sin revelar el resto de los datos.", en: "Proof of age or membership without revealing anything else." },
  "home.security.keys.title": { es: "Claves en hardware", en: "Keys in hardware" },
  "home.security.keys.body": { es: "Firma ES256 con claves gestionadas en AWS KMS: nunca salen del módulo.", en: "ES256 signatures with keys managed in AWS KMS: they never leave the module." },
  "home.security.revocation.title": { es: "Revocación en vivo", en: "Live revocation" },
  "home.security.revocation.body": { es: "Listas de estado estándar: una credencial revocada deja de verificar al momento.", en: "Standard status lists: a revoked credential stops verifying immediately." },
  "home.security.minimal.title": { es: "Datos mínimos", en: "Minimal data" },
  "home.security.minimal.body": { es: "Divulgación selectiva y datos pendientes cifrados; nada de más en los registros.", en: "Selective disclosure and encrypted pending data; nothing extra in the logs." },
