  "home.hero.kicker": { es: "Infraestructura de confianza para credenciales digitales", en: "Trust infrastructure for digital credentials" },
  "home.hero.title": { es: "Confianza que se puede verificar.", en: "Trust you can verify." },
  "home.hero.lead": { es: "CredoSeal permite a cualquier organización emitir credenciales digitales firmadas, entregarlas en la wallet de cada persona y verificarlas en segundos: sin llamadas, sin papeles y sin exponer más datos de los necesarios.", en: "CredoSeal lets any organization issue signed digital credentials, deliver them to each person's wallet and verify them in seconds: no calls, no paperwork, and no more data exposed than needed." },
  "home.hero.secondary": { es: "Ver cómo funciona", en: "See how it works" },
  "home.hero.note": { es: "Programa de fundadores · Gratis durante el lanzamiento · Sin tarjeta", en: "Founders program · Free during launch · No credit card" },
