  "home.problem.title": { es: "Un documento no prueba nada si no se puede comprobar.", en: "A document proves nothing if it can't be checked." },
  "home.how.kicker": { es: "Cómo funciona", en: "How it works" },
  "home.how.title": { es: "Emitir, entregar, verificar.", en: "Issue, deliver, verify." },
  "home.uses.kicker": { es: "Casos de uso", en: "Use cases" },
  "home.uses.title": { es: "Una plataforma, cualquier credencial.", en: "One platform, any credential." },
  "home.uses.lead": { es: "Donde haya algo que demostrar, hay una credencial que CredoSeal puede emitir y verificar.", en: "Wherever something needs proving, there's a credential CredoSeal can issue and verify." },
  "home.dev.kicker": { es: "Desarrolladores", en: "Developers" },
  "home.dev.title": { es: "Una API simple sobre estándares abiertos.", en: "A simple API on open standards." },
  "home.dev.body": { es: "Emita con una llamada, consulte el estado de cada credencial y verifique presentaciones de cualquier wallet compatible. Con documentación OpenAPI completa y claves de API con permisos acotados.", en: "Issue with a single call, check the status of every credential and verify presentations from any compatible wallet. With full OpenAPI documentation and narrowly scoped API keys." },
  "home.dev.link": { es: "Ver la referencia de la API →", en: "View the API reference →" },
  "home.security.kicker": { es: "Seguridad", en: "Security" },
