  "home.people.kicker": { es: "Para su equipo", en: "For your team" },
  "home.people.title": { es: "Hecha para personas. No hace falta programar.", en: "Built for people. No coding required." },
  "home.people.lead": { es: "Todo se hace desde un panel claro: defina sus credenciales con un formulario, emítalas y siga su estado desde el navegador. Si su equipo técnico quiere integrarlo con sus sistemas, también hay una API.", en: "Everything happens in a clear dashboard: define your credentials with a form, issue them and track their status from the browser. If your technical team wants to connect it to your systems, there's an API too." },
  "home.people.point.1": { es: "Plantillas con formularios, sin escribir código.", en: "Templates built with forms, no code to write." },
  "home.people.point.2": { es: "Una oferta en dos clics: un enlace y un código para la persona.", en: "An offer in two clicks: a link and a code for the person." },
