  "home.wallets.kicker": { es: "Wallets", en: "Wallets" },
  "home.wallets.title": { es: "Funciona con las wallets que ya usan.", en: "Works with the wallets people already use." },
  "home.wallets.lead": { es: "Cada persona recibe su credencial donde le resulta más cómodo, con el mismo enlace y el mismo código.", en: "Each person receives their credential wherever suits them best, with the same link and code." },
  "home.wallets.apple.title": { es: "Apple Wallet", en: "Apple Wallet" },
  "home.wallets.apple.body": { es: "Un pase en el iPhone con un código QR que cualquiera puede verificar.", en: "A pass on the iPhone with a QR code anyone can verify." },
  "home.wallets.google.title": { es: "Google Wallet", en: "Google Wallet" },
  "home.wallets.google.body": { es: "El mismo pase verificable en teléfonos Android.", en: "The same verifiable pass on Android phones." },
  "home.wallets.oid.title": { es: "Wallets de credenciales", en: "Credential wallets" },
  "home.wallets.oid.body": { es: "Compatibles con OpenID4VCI: la opción más privada, donde la persona elige qué datos mostrar.", en: "OpenID4VCI-compatible: the most private option, where the person chooses which data to show." },
  "home.verify.kicker": { es: "Verificación", en: "Verification" },
  "home.verify.title": { es: "Verificar es escanear un QR.", en: "Verifying is scanning a QR code." },
  "home.verify.lead": { es: "Quien recibe la credencial la escanea con la cámara del teléfono y ve al instante si es auténtica, quién la emitió y si sigue vigente. Sin cuenta y sin instalar nada.", en: "Whoever receives the credential scans it with their phone camera and instantly sees whether it's authentic, who issued it and whether it's still valid. No account, nothing to install." },
  "home.verify.point.1": { es: "Firma del emisor comprobada en cada lectura.", en: "The issuer's signature is checked on every scan." },
  "home.verify.point.2": { es: "Revocación en vivo: una credencial anulada deja de valer al momento.", en: "Live revocation: a cancelled credential stops working immediately." },
  "home.verify.point.3": { es: "Sólo los datos que la credencial muestra; nada queda guardado.", en: "Only the data the credential shows; nothing is stored." },
  "home.img.verify": { es: "/admin/static/home-mobile-verify-es.webp", en: "/admin/static/home-mobile-verify-en.webp" },
  "home.img.verify_alt": { es: "Resultado de verificación: credencial válida, firmada por el emisor", en: "Verification result: valid credential, signed by the issuer" },
  "home.aws.logo_alt": { es: "Powered by AWS", en: "Powered by AWS" },
  "home.aws.kms.title": { es: "Firma en hardware dedicado", en: "Signing in dedicated hardware" },
  "home.aws.kms.body": { es: "Claves ECDSA P-256 no exportables, generadas y custodiadas en módulos de seguridad de hardware validados FIPS 140-3: la clave privada nunca sale del módulo. Se rotan sin invalidar las credenciales ya emitidas.", en: "Non-exportable ECDSA P-256 keys, generated and held in FIPS 140-3 validated hardware security modules: the private key never leaves the module. They rotate without invalidating credentials already issued." },
  "home.aws.rds.title": { es: "Datos cifrados y recuperables", en: "Encrypted, recoverable data" },
  "home.aws.rds.body": { es: "Base de datos relacional gestionada, cifrada en reposo con claves propias y en tránsito con TLS; los datos pendientes de cada credencial llevan además cifrado de sobre por organización. Copias automáticas con recuperación a un punto en el tiempo.", en: "Managed relational database, encrypted at rest with our own keys and in transit with TLS; each credential's pending data also gets per-organization envelope encryption. Automatic backups with point-in-time recovery." },
  "home.aws.monitoring.title": { es: "Operación observada", en: "Observed operations" },
  "home.aws.monitoring.body": { es: "Métricas y alarmas sobre errores, latencia p95 y salud de cada tarea; registros estructurados y despliegues que vuelven solos a la versión anterior si la nueva falla.", en: "Metrics and alarms on errors, p95 latency and the health of every task; structured logs and deployments that roll back automatically if the new version fails." },
  "home.aws.kicker": { es: "Infraestructura", en: "Infrastructure" },
  "home.aws.title": { es: "Construida sobre AWS.", en: "Built on AWS." },
  "home.aws.lead": { es: "CredoSeal opera íntegramente sobre AWS, la misma infraestructura confiable y escalable que usa Amazon. La firma, los datos y la operación se apoyan en servicios gestionados con controles de seguridad auditados de forma independiente, no en servidores administrados a mano.", en: "CredoSeal runs entirely on AWS, the same reliable, scalable infrastructure that powers Amazon. Signing, data and operations rely on managed services with independently audited security controls, not on hand-run servers." },
