  "home.keys.title": { es: "Sus claves, sus reglas.", en: "Your keys, your rules." },
  "home.keys.lead": { es: "La clave que firma sus credenciales es el corazón de la confianza. Elija quién la custodia: nosotros, con todo resuelto, o usted, dentro de su propia infraestructura.", en: "The key that signs your credentials is the heart of trust. Choose who holds it: us, with everything taken care of, or you, inside your own infrastructure." },
  "home.keys.a.badge": { es: "Incluido", en: "Included" },
  "home.keys.a.title": { es: "Gestionada por CredoSeal", en: "Managed by CredoSeal" },
  "home.keys.a.body": { es: "Creamos y custodiamos una clave por organización en módulos de seguridad de hardware. Usted no gestiona infraestructura criptográfica: emite desde el primer día.", en: "We create and hold one key per organization in hardware security modules. You don't run any cryptographic infrastructure: you issue from day one." },
  "home.keys.a.point.1": { es: "Sin instalación ni equipo de seguridad propio.", en: "No installation, no in-house security team." },
  "home.keys.a.point.2": { es: "Rotación y publicación de claves resueltas.", en: "Key rotation and publication handled for you." },
  "home.keys.a.point.3": { es: "Ideal para instituciones, empresas y asociaciones que quieren empezar ya.", en: "Ideal for institutions, companies and associations that want to start now." },
  "home.keys.b.badge": { es: "Enterprise · a pedido", en: "Enterprise · on request" },
  "home.keys.b.title": { es: "Su clave, su infraestructura", en: "Your key, your infrastructure" },
  "home.keys.b.body": { es: "La clave privada se queda en su HSM o en el servicio de claves de su propia nube. CredoSeal sólo le pide firmas y usted puede retirar ese permiso cuando quiera.", en: "The private key stays in your HSM or in your own cloud's key service. CredoSeal only requests signatures, and you can withdraw that permission at any time." },
  "home.keys.b.point.1": { es: "Soberanía y cumplimiento: la clave nunca sale de su control.", en: "Sovereignty and compliance: the key never leaves your control." },
  "home.keys.b.point.2": { es: "Compatible con HSM on-premise y servicios de claves en la nube.", en: "Works with on-premise HSMs and cloud key services." },
  "home.keys.b.point.3": { es: "Pensado para gobiernos, bancos, salud y sectores regulados.", en: "Built for government, banking, healthcare and regulated sectors." },
