  "home.demo.title": { es: "Tenga una credencial en su teléfono en un minuto.", en: "Get a credential on your phone in a minute." },
  "home.demo.lead": { es: "Sin cuenta y sin hablar con nadie: emitimos una credencial de muestra a su nombre, la agrega a su wallet y la verifica usted mismo.", en: "No account and no sales call: we issue a sample credential in your name, you add it to your wallet and verify it yourself." },
