  "home.open.kicker": { es: "Sin dependencia", en: "No lock-in" },
  "home.open.title": { es: "Estándares abiertos. Sin quedar atado.", en: "Open standards. No lock-in." },
  "home.open.lead": { es: "Sus credenciales usan estándares internacionales abiertos, no un formato propietario. Funcionan con cualquier wallet y cualquier verificador compatibles, hoy y mañana.", en: "Your credentials use open international standards, not a proprietary format. They work with any compatible wallet and any compatible verifier, today and tomorrow." },
  "home.open.1.title": { es: "Formatos abiertos", en: "Open formats" },
  "home.open.1.body": { es: "SD-JWT VC, OpenID4VCI y OpenID4VP: especificaciones públicas de IETF y la OpenID Foundation, no inventos nuestros.", en: "SD-JWT VC, OpenID4VCI and OpenID4VP: public specifications from the IETF and the OpenID Foundation, not something we made up." },
  "home.open.2.title": { es: "Cualquier wallet compatible", en: "Any compatible wallet" },
  "home.open.2.body": { es: "Además de Apple y Google Wallet, la persona puede guardar su credencial en la wallet compatible que prefiera.", en: "Besides Apple and Google Wallet, people can keep their credential in any compatible wallet they prefer." },
  "home.open.3.title": { es: "Cualquier verificador compatible", en: "Any compatible verifier" },
  "home.open.3.body": { es: "Quien verifica no necesita ser cliente de CredoSeal: cualquier software que implemente el estándar comprueba la firma y la revocación.", en: "Verifiers don't need to be CredoSeal customers: any software implementing the standard checks the signature and revocation." },
  "home.open.fine": { es: "Son los mismos estándares adoptados por la wallet de identidad digital de la Unión Europea.", en: "These are the same standards adopted by the European Union Digital Identity Wallet." },
