  "home.faq.kicker": { es: "Preguntas frecuentes", en: "FAQ" },
  "home.faq.title": { es: "Lo que suelen preguntarnos.", en: "What people usually ask us." },
  "home.faq.lead": { es: "¿Otra duda? Escríbanos a <a class=\"text-link\" href=\"mailto:hello@credoseal.com\">hello@credoseal.com</a>.", en: "Another question? Write to us at <a class=\"text-link\" href=\"mailto:hello@credoseal.com\">hello@credoseal.com</a>." },
  "home.faq.1.q": { es: "¿La persona que recibe la credencial tiene que instalar algo?", en: "Does the person receiving the credential need to install anything?" },
  "home.faq.1.a": { es: "No. La agrega a Apple Wallet o Google Wallet, que ya vienen en su teléfono. Si prefiere más privacidad, puede usar cualquier wallet de credenciales compatible con OpenID4VCI.", en: "No. They add it to Apple Wallet or Google Wallet, which already come with their phone. For more privacy, they can use any OpenID4VCI-compatible credential wallet." },
  "home.faq.2.q": { es: "¿Quién puede verificar y cuánto le cuesta?", en: "Who can verify, and what does it cost them?" },
  "home.faq.2.a": { es: "Cualquiera, gratis y sin cuenta: escanea el QR con la cámara del teléfono y ve al instante si la credencial es auténtica, quién la emitió y si sigue vigente.", en: "Anyone, for free and without an account: they scan the QR code with their phone's camera and instantly see whether the credential is authentic, who issued it and whether it's still valid." },
  "home.faq.3.q": { es: "¿Qué pasa si una credencial deja de ser válida?", en: "What if a credential stops being valid?" },
  "home.faq.3.a": { es: "La revoca con un botón desde el panel (o la API). Desde ese momento, toda verificación la muestra como revocada, aunque la persona conserve el pase en su teléfono.", en: "You revoke it with one click in the panel (or via the API). From then on, every check shows it as revoked, even if the person still has the pass on their phone." },
  "home.faq.4.q": { es: "¿Qué datos personales guardan?", en: "What personal data do you keep?" },
  "home.faq.4.a": { es: "Los mínimos. Los datos de cada credencial se guardan cifrados sólo hasta que la persona la recibe y luego se borran; la credencial vive en su wallet. Al verificar no queda guardado el contenido.", en: "As little as possible. Each credential's data is stored encrypted only until the person receives it, and then deleted; the credential lives in their wallet. Verifying doesn't store its contents." },
  "home.faq.5.q": { es: "¿Necesito un equipo técnico?", en: "Do I need a technical team?" },
  "home.faq.5.a": { es: "No. Todo se hace desde el panel con formularios. Si más adelante quiere emitir desde sus sistemas, la misma funcionalidad está en la API.", en: "No. Everything is done from the panel with forms. If you later want to issue from your own systems, the same features are in the API." },
  "home.faq.6.q": { es: "¿Puedo usar mi propia clave de firma?", en: "Can I use my own signing key?" },
  "home.faq.6.a": { es: "Sí, en el plan Enterprise: la clave queda en su HSM o en el servicio de claves de su nube, y CredoSeal sólo le pide firmas.", en: "Yes, on the Enterprise plan: the key stays in your HSM or your cloud's key service, and CredoSeal only asks it for signatures." },
  "home.faq.7.q": { es: "¿Cuánto tarda en tener acceso?", en: "How long until I get access?" },
  "home.faq.7.a": { es: "Revisamos cada solicitud y respondemos en uno o dos días hábiles. Con el acceso, puede emitir su primera credencial el mismo día.", en: "We review each request and reply within one or two business days. Once you have access, you can issue your first credential the same day." },
  "home.founders.1": { es: "Gratis durante todo el lanzamiento.", en: "Free for the whole launch period." },
  "home.founders.2": { es: "Precio de fundador garantizado cuando lleguen los planes de pago.", en: "A guaranteed founder price when paid plans arrive." },
  "home.founders.3": { es: "Acompañamiento directo hasta emitir su primera credencial.", en: "Hands-on help until you issue your first credential." },
  "home.founders.4": { es: "Voz en la hoja de ruta: lo que necesita, lo priorizamos.", en: "A say in the roadmap: what you need, we prioritize." },
  "home.form.next": { es: "Le respondemos en uno o dos días hábiles. ¿Prefiere conversar? <a class=\"text-link\" href=\"mailto:hello@credoseal.com?subject=Demo%20de%20CredoSeal\">Pida una demo de 20 minutos</a>.", en: "We reply within one or two business days. Rather talk? <a class=\"text-link\" href=\"mailto:hello@credoseal.com?subject=CredoSeal%20demo\">Ask for a 20-minute demo</a>." },
  "login.home": { es: "Ir a la página de inicio de CredoSeal", en: "Go to the CredoSeal home page" },
  "login.home_link": { es: "← Volver al inicio", en: "← Back to home" },
